"""Review the statute and distinguish historical modifying fragments from current law."""
import json
from pathlib import Path
P='https://www.planalto.gov.br/ccivil_03/'
D={
1:('O rol legal abrange tentativa e consumação, com hipóteses específicas: não basta gravidade intuitiva. Atualizações incluem feminicídio autônomo (2024), ampliação de proteção funcional e lesão gravíssima/seguida de morte em ensino (2025), vicaricídio, domínio social estruturado/favorecimento e expansão dos crimes sexuais do ECA enumerados (2026). Diferencie estupro, modalidades de roubo/extorsão, epidemia com morte, medicamentos, exploração sexual, furto com explosivo, suicídio/automutilação por meios digitais, cárcere de menor e tráfico de pessoas contra criança/adolescente.', 'Rol e remissão exata: posse/porte de arma de uso proibido, comércio ilegal e tráfico internacional; organização voltada a hediondo/equiparado; correspondência militar; delitos do ECA expressamente enumerados.', 'Não tornar todo roubo, furto, arma restrita, tráfico de pessoas contra adulto ou organização automaticamente hediondo. A inclusão mais gravosa exige análise temporal. A nova lei cita §3º vetado no domínio social: remissão não cria tipo vetado.', 'Roubo com arma de fogo preenche hipótese específica; furto simples não entra por mera gravidade subjetiva.', 'É posse/porte de arma apenas restrita: compare a hipótese de uso proibido do inciso II, sem confundir com outros crimes do estatuto.', 'Todo roubo é hediondo apenas pelo nome do crime? Não; devem ser verificadas as modalidades do rol.'),
2:('Hediondos e equiparados são insuscetíveis de anistia, graça, indulto e fiança. Isso não equivale à proibição automática de liberdade provisória. STF afastou regime inicial fechado baseado exclusivamente na hediondez. Progressão deve ser estudada na LEP 112 atual, não nos percentuais do antigo §2º revogado. Temporária: 30 dias mais 30 em extrema/comprovada necessidade, com requisitos constitucionais. Apelar em liberdade exige decisão fundamentada.', 'Tortura, terrorismo e tráfico ilícito equiparados; tráfico privilegiado não tem natureza hedionda (STF).', 'Não impor fechado automático ou confundir inafiançabilidade com prisão obrigatória. STJ, Informativo 882/2026: fabricação de maquinário (drogas 34) não é equiparada; associação (35) também não recebe hediondez por analogia.', 'A pena exige regime individualizado conforme requisitos, sem fundamentar apenas no rótulo hediondo.', 'A acusação é art. 34 da Lei de Drogas: aplique a distinção recente do STJ, não chame todo delito daquela lei equiparado.', 'Inafiançabilidade significa prisão obrigatória sem exame de liberdade provisória? Não; são questões distintas.'),
3:('A União mantém estabelecimentos de segurança máxima para condenados de alta periculosidade cuja permanência estadual ponha em risco ordem/incolumidade pública. Recolhimento e transferência têm procedimentos próprios; o texto não ordena enviar todo condenado por hediondo ao sistema federal.', 'Alta periculosidade + risco da permanência estadual; procedimento próprio.', 'Distinguir regra geral de hipóteses federais específicas de leis posteriores, como crimes dos arts. 21-A/B da Lei 12.850.', 'O caso evidencia risco concreto no estabelecimento estadual e se examina o procedimento de transferência.', 'Só há o rótulo hediondo: isso não prova todos os elementos deste artigo.', 'Todo condenado por hediondo vai automaticamente ao presídio federal por este artigo? Não; há condições e procedimento próprios.'),
5:('Introduziu no CP 83, V livramento após mais de dois terços, sem reincidência específica, para os crimes indicados. A redação atual também inclui tráfico de pessoas desde 2016. Outros requisitos do CP 83 e vedações especiais atuais precisam ser verificados; não é a fração da progressão.', 'Mais de 2/3, não exatamente 2/3; livramento ≠ progressão.', 'Não prometer benefício só pelo tempo. Domínio social tem proibição específica; LEP/leis especiais podem impor outras restrições conforme hipótese e data do fato.', 'Cumpre mais de dois terços e satisfaz os demais requisitos: examina-se possibilidade, não direito automático pelo relógio.', 'O crime tem vedação especial de livramento: não se ignora a restrição apenas citando CP 83.', 'A fração do artigo é critério de progressão de regime? Não; trata de livramento condicional.'),
6:('Artigo modificador com penas e remissões históricas. No CP 157 atual, lesão grave no roubo é 7 a 18 anos e multa; latrocínio geral passou a 24 a 30 anos e multa pela Lei 15.397/2026, além de hipóteses específicas do marco antifacção. Os arts. 214 e 223 foram revogados em 2009; consulte CP 213 e 217-A e demais tipos vigentes.', 'CP compilado prevalece para estudar a pena atual; fragmento de 1990 não é quadro atual completo.', 'Não memorizar 5–15/20–30 do roubo transcrito como penas gerais atuais. Não reutilizar tipos sexuais revogados nem combinar artificialmente penas de épocas diferentes.', 'A prova cobra latrocínio atual e o candidato consulta CP 157, §3º, II, com a alteração de 2026.', 'Apostila reproduz a faixa de 1990: identifique o trecho como histórico e confira a fonte alterada.', 'O trecho de 1990 contém todas as penas atuais do roubo? Não; houve alterações posteriores, inclusive em 2026.'),
7:('Introduziu redução no sequestro por colaboração. O CP 159, §4º foi alterado em 1996: crime cometido em concurso, e concorrente que denuncia à autoridade facilitando libertação tem redução de 1/3 a 2/3. A redação atual não exige necessariamente antiga quadrilha/bando.', 'Atual: concurso + contribuição efetiva à libertação; redução 1/3–2/3.', 'Denúncia sem facilitar libertação não concede redutor automático. Não exigir antigo número de quadrilha para a redação atual.', 'Dois concorrentes praticam extorsão mediante sequestro e um denuncia, facilitando libertação: examine §4º atual.', 'Relata fato já encerrado sem facilitar libertação: a eficácia típica precisa ser demonstrada.', 'A redação atual exige necessariamente quadrilha ou bando? Não; desde 1996 refere-se ao crime cometido em concurso.'),
8:('Pena de 3 a 6 anos para associação do CP 288 voltada aos crimes indicados. Desmantelamento possibilitado pela denúncia do participante/associado permite redução de 1/3 a 2/3. Associação para o tráfico atual é tipo especial da Lei 11.343, art. 35, com 3 a 10 anos e dias-multa; não se substitui sua pena por este artigo.', 'CP 288 especial versus drogas 35; não confundir com organização de 4+.', 'Associação para o tráfico não é automaticamente hedionda. STJ, Tema 1355/2026: fração especial do art. 44 da Lei de Drogas para livramento aplica-se ao art. 35, embora não hediondo. Benefício não se deduz só da etiqueta.', 'Associação estável para tráfico é analisada pela lei especial e seus requisitos.', 'É associação do CP 288 para crimes hediondos: analise a hipótese deste artigo, sem transplantar elementos de organização.', 'A pena atual do art. 35 da Lei de Drogas vira automaticamente três a seis anos? Não; a lei especial prevê três a dez anos e multa.'),
9:('O texto conserva antiga majorante ligada ao CP 224, revogado pela Lei 12.015/2009. STJ reconheceu o afastamento da causa de aumento do art. 9º com essa reforma. Para fatos atuais, não aplique a metade por esta remissão; consulte tipos e majorantes vigentes. Casos antigos exigem comparação integral e lei mais benéfica, sem mistura artificial.', 'Remissão histórica ao CP 224 revogado; majorante afastada pela reforma.', 'O limite de trinta anos do trecho histórico também não é o teto geral atual do CP 75. Não reconstruir vulnerabilidade atual pelo art. 224 revogado.', 'Questão atual tenta aumentar metade invocando art. 224: identifique a remissão superada.', 'O fato precede 2009: compare regimes e jurisprudência de sucessão, sem somar partes mais benéficas de leis distintas automaticamente.', 'A remissão ao CP 224 fornece majorante geral vigente para fatos atuais? Não; é remissão histórica superada pela reforma.'),
10:('Modificou prazos da antiga Lei de Drogas 6.368/1976, revogada pela Lei 11.343/2006. Para procedimentos atuais, consulte a lei nova e CPP aplicável; não dobre prazos atuais apenas com esta reprodução.', 'Lei 6.368 revogada; procedimento atual na Lei 11.343.', 'Não confundir histórico de prazos em dobro com regra geral atual de toda investigação sobre drogas.', 'A questão cobra prazo atual e o aluno busca a disciplina da lei vigente.', 'A apostila aplica automaticamente a antiga duplicação: verifique a hipótese normativa atual antes de usar.', 'A transcrição da lei revogada dobra automaticamente todos os prazos atuais de drogas? Não; consulte a disciplina vigente.'),
12:('A lei original entrou em vigor na publicação. Novas inclusões e penas seguem os marcos de seus atos, observada irretroatividade mais gravosa e retroatividade benéfica.', 'Vigência original na publicação; cada alteração tem data própria.', 'Não usar data de consulta para escolher lei do fato nem presumir que todas as inclusões vigoram desde 1990.', 'O fato ocorreu antes da inclusão de um novo delito no rol: examine a lei temporalmente aplicável.', 'A alteração beneficia condenado: examine possibilidade de retroatividade benéfica.', 'Todas as inclusões posteriores são aplicáveis desde 1990? Não; possuem marcos próprios.'),
13:('Revoga disposições contrárias à lei original; não dispensa verificar revogações e alterações posteriores no CP e leis especiais.', 'Leia a compilação do diploma alterado, não somente o modificador.', 'A cláusula não torna vigentes novamente CP 214/223 ou Lei 6.368 revogados depois.', 'O material mantém tipo antigo e o aluno confere a revogação na lei alterada.', 'A cláusula genérica é invocada para ignorar a lei posterior: ela não impede sucessão legislativa.', 'A cláusula mantém vigentes tipos posteriormente revogados? Não; alterações posteriores devem ser observadas.'),
159:('Fragmento de penas do sequestro: caput 8–15 anos; qualificadas 12–20, 16–24 e 24–30. Consulte CP 159 completo para duração superior a 24h, idades, concurso e colaboração; em 2026, §5º acrescentou aumento de 2/3 no contexto específico do marco antifacção.', 'Penas do fragmento não esgotam qualificadoras e majorante atual.', 'Não deduzir elementos do crime de linhas pontilhadas. Exatamente 24h não significa mais de 24h; maior de 60 não equivale literalmente a 60 completos.', 'O fato ocorre no contexto de atuação definido no §5º e se examina a majorante de 2026.', 'O candidato só memoriza o fragmento: perde requisitos de qualificadoras e regra posterior.', 'O fragmento reproduz o §5º acrescido em 2026? Não; é necessário consultar o CP atualizado.'),
213:('Reproduz apenas pena antiga de 6 a 10 anos, coincidente com caput atual, mas não o tipo completo. Desde 2009, CP 213 abrange constranger alguém mediante violência/grave ameaça à conjunção ou outro ato libidinoso, com qualificadas de lesão grave e morte. Estupro de vulnerável tem tipo próprio no CP 217-A.', 'Pena coincidente não torna a reprodução antiga uma explicação atual completa.', 'Não limitar estupro a vítima mulher/conjunção nem usar CP 214/223 revogados para os atos atuais.', 'O constrangimento envolve outro ato libidinoso com grave ameaça: examina-se CP 213 atual.', 'A vulnerabilidade própria do 217-A exige analisar esse tipo, não apenas a pena do fragmento.', 'A pena isolada substitui o estudo do tipo e qualificadoras atuais? Não; consulte o CP 213 completo.'),
214:('Reprodução histórica do antigo atentado violento ao pudor. O CP 214 foi revogado em 2009; condutas precisam ser examinadas nos tipos atuais, especialmente CP 213 e 217-A, conforme elementos. Revogação do número não é impunidade automática de toda conduta.', 'CP 214 revogado; analisar continuidade e tipo atual.', 'Não oferecer lacuna automática para memorizar artigo revogado como vigente nem afirmar abolitio criminis geral.', 'A questão atual descreve ato libidinoso com violência e é comparada ao CP 213.', 'O caso é anterior à reforma: examine sucessão e regime aplicável, sem presumir que toda conduta desapareceu.', 'O CP 214 continua como tipo vigente para fatos atuais? Não; foi revogado e exige análise dos tipos atuais.'),
223:('Trecho histórico de resultados qualificados de crimes sexuais. CP 223 foi revogado em 2009. Qualificadoras atuais de lesão/morte estão nos respectivos tipos, como CP 213/217-A, com penas próprias; faixas deste fragmento não são quadro atual.', 'Resultado qualificado: consultar tipo vigente, não CP 223.', 'Não transportar 8–12/12–25 anos indiscriminadamente para todos os crimes sexuais atuais.', 'A prova cobra resultado morte no estupro: consulta-se a qualificadora do tipo atual.', 'Usa-se a faixa de 12–25 deste fragmento: é referência histórica, não pena universal vigente.', 'As penas do CP 223 reproduzido regem automaticamente crimes sexuais atuais? Não; o artigo foi revogado.'),
267:('O fragmento fixa epidemia dolosa em 10 a 15 anos, pena mantida no CP 267. Resultado morte dobra a pena e integra o rol hediondo; modalidade culposa tem penas próprias e não se equipara automaticamente à dolosa com morte.', 'Epidemia dolosa com morte é hipótese do rol; nem toda epidemia é hedionda.', 'Linhas omitidas escondem resultados e culpa: consultar CP completo.', 'Há propagação dolosa de germes e morte: examine §1º e rol.', 'A conduta é culposa: não aplique automaticamente a pena da modalidade dolosa.', 'Toda modalidade de epidemia é hedionda? Não; o rol indica epidemia com resultado morte na hipótese legal.'),
270:('Envenenar água potável ou substância alimentícia/medicinal destinada ao consumo: CP 270 doloso com 10 a 15 anos; também inclui entregar ao consumo/depositar para distribuir o envenenado. A modalidade culposa tem 6 meses a 2 anos. Ter pena alta ou estar alterado nesta lei não torna o crime automaticamente hediondo no rol atual.', 'Artigo modificador ≠ inclusão permanente no rol atual.', 'Não confundir CP 270 com falsificação medicinal do CP 273 nem epidemia com morte do CP 267, §1º.', 'A questão pergunta classificação atual do envenenamento e se consulta o rol, não apenas a localização do fragmento.', 'É adulteração medicinal do CP 273: analise os elementos e previsão específica, sem trocar artigos.', 'Estar reproduzido nesta lei torna automaticamente CP 270 hediondo no rol atual? Não; classificação depende do rol vigente.')
}
def write():
 units={f'art-{n}':dict(simples=s,pontos=[p],atencao=[a],exemplo=e+' Variação: '+v,prova=[q],termos=[],remissoes=[]) for n,(s,p,a,e,v,q) in D.items()}
 for n in [1,5,6,7,8,9,13,159,213,214,223,267,270]:units[f'art-{n}']['remissoes']=[P+'decreto-lei/del2848compilado.htm']
 units['art-1']['remissoes'] += [P+'_ato2023-2026/2026/lei/l15358.htm',P+'_ato2023-2026/2026/lei/l15384.htm',P+'_ato2023-2026/2026/lei/l15487.htm']
 units['art-2']['remissoes']=[P+'leis/l7210.htm','https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=361875','https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=319638','https://processo.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisar&aplicacao=informativo&livre=%40CNOT%3D022206']
 units['art-6']['remissoes'].append(P+'_ato2023-2026/2026/lei/l15397.htm')
 units['art-7']['remissoes'].append(P+'leis/l9269.htm')
 units['art-8']['remissoes'] += [P+'_ato2004-2006/2006/lei/l11343.htm','https://processo.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisar&livre=multa+']
 units['art-9']['remissoes'].append('https://www.stj.jus.br/websecstj/cgi/revista/REJ.cgi/ITA?CodOrgaoJgdr=&SeqCgrmaSessao=&dt=20180822&formato=PDF&nreg=201701589314&salvar=false&seq=1732343&tipo=0')
 units['art-10']['remissoes']=[P+'_ato2004-2006/2006/lei/l11343.htm']
 units['art-2']['prova'].append('O tráfico privilegiado tem natureza hedionda? Não; o STF afastou essa natureza na hipótese do art. 33, §4º.')
 Path('scripts/explicacoes/hediondos-revisao-aplicada-2026-10-11.json').write_text(json.dumps(dict(course_slug='hediondos',units=units),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print(len(units),'explicitly authored articles')
if __name__=='__main__':write()
